const { timingSafeEqual } = require('crypto');

// Client id = id del canal en OmniDesk. Secret = secreto HMAC de Generar credenciales.
const CLIENT_ID = 'REEMPLAZA_CLIENT_ID';
const CLIENT_SECRET = 'REEMPLAZA_CLIENT_SECRET';

function same(left, right) {
  const a = Buffer.from(String(left));
  const b = Buffer.from(String(right));
  return a.length > 0 && a.length === b.length && timingSafeEqual(a, b);
}

const item = $input.first();
const headers = item.json.headers ?? {};
const clientId = headers['x-client-id'];
const clientSecret = headers['x-client-secret'];
let body = item.json.body;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch {
    body = null;
  }
}

if (!same(clientId, CLIENT_ID) || !same(clientSecret, CLIENT_SECRET) || !body || typeof body !== 'object') {
  return [{ json: { statusCode: 401, reply: { ok: false } } }];
}

if (body.type === 'ping') {
  return [{ json: { statusCode: 200, reply: { ok: true } } }];
}

if (body.type === 'ai.reply') {
  return [{ json: { statusCode: 501, reply: { ok: false } } }];
}

return [{ json: { statusCode: 400, reply: { ok: false } } }];
